# Simple stub for calculate_stock_volatility for testing  
def calculate_stock_volatility(prices):
    # For this test, return the stddev of differences between prices (very rough)
    if len(prices) < 2:
        return 0.0
    diffs = [prices[i+1] - prices[i] for i in range(len(prices)-1)]
    mean = sum(diffs)/len(diffs)
    var = sum((d-mean)**2 for d in diffs)/len(diffs)
    return var**0.5

