    expected = v1 * 0.5 + v2 * 0.5
    assert round(portfolio_risk_assessment({
        'MSFT': {'prices': [10, 20, 30], 'allocation': 0.5},
        'GOOG': {'prices': [100, 95, 105], 'allocation': 0.5}
    }), 6) == round(expected, 6), \
        "Two stocks, equal allocations"

    # Zero allocation for one stock
    v3 = fake_volatility([5, 5, 5, 5])
    assert portfolio_risk_assessment({
        'TSLA': {'prices': [5, 5, 5, 5], 'allocation': 0.0},
        'AMZN': {'prices': [20, 25, 30, 35], 'allocation': 1.0}
    }) == fake_volatility([20, 25, 30, 35]), \
        "Zero allocation stock does not contribute"

    # Stocks with different volatilities and allocations
