# Multiple stocks with different allocation and volatilities
# For example,
# Stock 1: prices=[100, 105, 110], allocation=0.6
# Stock 2: prices=[200, 195, 205], allocation=0.4
# If calculate_stock_volatility returns 5.0 for stock 1 and 5.0 for stock 2, expected risk = 5.0*0.6 + 5.0*0.4 = 5.0

# To ensure correctness, assume calculate_stock_volatility returns the sample standard deviation
import math
def calculate_stock_volatility(prices):
    n = len(prices)
    if n < 2:
        return 0.0
    mean = sum(prices) / n
    variance = sum((p - mean)**2 for p in prices) / (n - 1)
    return math.sqrt(variance)

def test_portfolio_risk_assessment():
    # Patch the real function for tests
    global calculate_stock_volatility
    calculate_stock_volatility_backup = calculate_stock_volatility

    # Test 1: No stocks
    assert portfolio_risk_assessment({}) == 0.0, "Empty dict should return zero risk."

    # Test 2: Single stock with constant price
    assert portfolio_risk_assessment({'AAPL': {'prices': [50, 50, 50], 'allocation': 1.0}}) == 0.0, "Zero volatility, allocation 1."

    # Test 3: Single stock, allocation < 1
    # Prices: [100, 110, 90]
    expected_volatility = calculate_stock_volatility([100, 110, 90])
    expected_risk = expected_volatility * 0.5
    assert portfolio_risk_assessment({'MSFT': {'prices': [100, 110, 90], 'allocation': 0.5}}) == expected_risk, "Single stock, allocation 0.5"

    # Test 4: Two stocks, allocations that sum to 1
    prices1 = [10, 20, 30]
    prices2 = [100, 110, 120]
    vol1 = calculate_stock_volatility(prices1)
    vol2 = calculate_stock_volatility(prices2)
    alloc1, alloc2 = 0.3, 0.7
    expected_risk = vol1 * alloc1 + vol2 * alloc2
    portfolio = {
        'AAA': {'prices': prices1, 'allocation': alloc1},
        'BBB': {'prices': prices2, 'allocation': alloc2},
    }
    assert portfolio_risk_assessment(portfolio) == expected_risk, "Two stocks with allocations summing to 1"

    # Test 5: Allocation sums to less than 1
    pricesa = [12, 18, 14]
    pricesb = [50, 48, 52]
    vola = calculate_stock_volatility(pricesa)
    volb = calculate_stock_volatility(pricesb)
    alloc_a, alloc_b = 0.2, 0.2
    expected_risk = vola * alloc_a + volb * alloc_b
    portfolio = {
        'X': {'prices': pricesa, 'allocation': alloc_a},
        'Y': {'prices': pricesb, 'allocation': alloc_b},
    }
    assert portfolio_risk_assessment(portfolio) == expected_risk, "Allocations sum to less than 1"

    # Test 6: Allocation is zero for some stocks
    prices = [5, 6, 7]
    assert portfolio_risk_assessment({'NOP': {'prices': prices, 'allocation': 0.0}}) == 0.0, "Allocation zero, risk zero"

    # Test 7: Portfolio with a stock with 1 price (volatility zero)
    assert portfolio_risk_assessment({'SINGLE': {'prices': [100], 'allocation': 0.5}}) == 0.0, "Single price, volatility zero"

    calculate_stock_volatility = calculate_stock_volatility_backup

test_portfolio_risk_assessment()
